mapper.select:
SELECT id, record_date, style_breakdown, selected_tags, reason_tags, fact_bomb, created_at
FROM style_analysis
WHERE record_date = #{recordDate}

mapper.update:
UPDATE style_analysis
SET selected_tags = #{selectedTags}, reason_tags = #{reasonTags}
WHERE record_date = #{recordDate}

UPDATE style_analysis
SET style_breakdown = #{styleBreakdown}
WHERE record_date = #{recordDate}

UPDATE style_analysis
SET fact_bomb = #{factBomb}
WHERE record_date = #{recordDate}
